import { motion, useTransform } from 'framer-motion';
import type { MotionValue } from 'framer-motion';
import ScrollShell from './ScrollShell';

const LINES = [
  '有些句子值得被等待',
  '它们藏在遮罩之下',
  '随着你向下滑动',
  '一行一行揭开面纱',
  '先是轮廓 再是墨色',
  '最后连模糊都散去',
];

const N = LINES.length;

function Line({
  progress,
  index,
  text,
}: {
  progress: MotionValue<number>;
  index: number;
  text: string;
}) {
  // Each line owns a strictly-increasing slice of progress.
  const start = 0.06 + index * 0.13;
  const end = Math.min(1, start + 0.16);
  const y = useTransform(progress, [start, end], ['110%', '0%']);
  const blur = useTransform(progress, [start + 0.03, end], ['blur(6px)', 'blur(0px)']);
  const opacity = useTransform(progress, [start, start + 0.04], [0, 1]);

  return (
    <div className="overflow-hidden py-0.5">
      <motion.p
        style={{ y, filter: blur, opacity }}
        className="text-[19px] font-medium leading-snug tracking-wide text-zinc-950"
      >
        {text}
      </motion.p>
    </div>
  );
}

/**
 * 逐行揭示 — six lines, each wrapped in an overflow-hidden mask, slide up
 * 110% → 0 over their own slice of scrollYProgress while a 6px blur clears.
 * Unlike per-character lighting, the whole line surfaces at once.
 */
export default function LineRevealScroll() {
  return (
    <ScrollShell>
      {({ progress }) => (
        <div className="relative h-[760px]">
          <div className="sticky top-0 flex h-[320px] flex-col justify-center px-9">
            <span className="mb-5 font-mono text-[10px] uppercase tracking-[0.2em] text-zinc-400">
              Line by line
            </span>
            <div>
              {LINES.map((text, i) => (
                <Line key={i} progress={progress} index={i} text={text} />
              ))}
            </div>
            <span className="mt-5 font-mono text-[10px] uppercase tracking-[0.2em] text-zinc-300">
              {String(N).padStart(2, '0')} lines · masked reveal
            </span>
          </div>
        </div>
      )}
    </ScrollShell>
  );
}

import { useRef } from 'react';
import type { ReactNode, RefObject } from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';
import type { MotionValue } from 'framer-motion';
import { ArrowDown } from 'lucide-react';
import { cn } from '@/lib/utils';

const css = `
.mv-scroll {
  scrollbar-width: thin;
  scrollbar-color: #d4d4d8 transparent;
}
.mv-scroll::-webkit-scrollbar {
  width: 4px;
}
.mv-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.mv-scroll::-webkit-scrollbar-thumb {
  background: #d4d4d8;
  border-radius: 999px;
}
`;

export type ScrollCtx = {
  scrollerRef: RefObject<HTMLDivElement | null>;
  progress: MotionValue<number>;
};

type ScrollShellProps = {
  children: (ctx: ScrollCtx) => ReactNode;
  /** extra classes for the inner scroller (width / background overrides) */
  className?: string;
};

/**
 * Internal-scroll-container pattern shared by every scroll-narrative preview:
 * a 320px overflow-y viewport (page scroll is never hijacked) with a thin
 * custom scrollbar, a scroll-progress hairline pinned to the top, and a
 * "向下滚动" hint pill that fades out as soon as scrolling starts.
 * Children receive the container ref + a 0→1 scrollYProgress MotionValue.
 */
export default function ScrollShell({ children, className }: ScrollShellProps) {
  const scrollerRef = useRef<HTMLDivElement | null>(null);
  const { scrollYProgress } = useScroll({ container: scrollerRef });
  const hintOpacity = useTransform(scrollYProgress, [0, 0.06], [1, 0]);

  return (
    <div className="flex h-full w-full items-center justify-center">
      <style>{css}</style>
      <div className="relative flex w-full justify-center">
        <div
          ref={scrollerRef}
          /* Lenis 会在文档级劫持 wheel 事件，导致此容器只能拖滚动条；
             data-lenis-prevent 让滚轮在此容器内恢复原生滚动。 */
          data-lenis-prevent
          className={cn(
            'mv-scroll relative h-[320px] w-[400px] max-w-full overflow-y-auto overscroll-contain rounded-xl border border-zinc-200 bg-white',
            className,
          )}
        >
          <motion.div
            className="sticky top-0 z-40 h-0.5 origin-left bg-zinc-950/80"
            style={{ scaleX: scrollYProgress }}
          />
          {children({ scrollerRef, progress: scrollYProgress })}
        </div>
        <motion.div
          style={{ opacity: hintOpacity }}
          className="pointer-events-none absolute bottom-3 left-1/2 z-40 flex -translate-x-1/2 items-center gap-1.5 rounded-full border border-zinc-200 bg-white/90 px-2.5 py-1 text-[11px] text-zinc-500 shadow-sm backdrop-blur"
        >
          <motion.span
            animate={{ y: [0, 3, 0] }}
            transition={{ duration: 1.4, repeat: Infinity, ease: 'easeInOut' }}
            className="flex"
          >
            <ArrowDown className="h-3 w-3" />
          </motion.span>
          向下滚动
        </motion.div>
      </div>
    </div>
  );
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

